package me.pikanote.companion;
import android.app.Instrumentation;import android.content.*;import org.json.*;import java.io.*;
final class AskOrderingChecks{
 static void run(Instrumentation i)throws Exception{File root=new File(i.getTargetContext().getFilesDir(),"ask-order-test");root.mkdirs();Context box=new ContextWrapper(i.getTargetContext()){public File getFilesDir(){return root;}};try{Store store=new Store(box);JSONArray turns=new JSONArray().put(new JSONObject().put("id","first").put("createdUtc","2026-11-01T00:00:00Z")).put(new JSONObject().put("id","unknown").put("createdUtc","")).put(new JSONObject().put("id","next").put("createdUtc","2026-11-02T00:00:00Z"));store.state.put("askTurns",turns);JSONArray ordered=PhoneAsk.ordered(store);if(!ordered.getJSONObject(1).getString("id").equals("unknown")||!ordered.getJSONObject(1).getString("createdUtc").isEmpty())throw new Exception("Undated source order lost or timestamp invented");turns.put(new JSONObject().put("id","latest").put("createdUtc",""));if(!PhoneAsk.ordered(store).getJSONObject(3).getString("id").equals("latest"))throw new Exception("Latest undated Ask moved to beginning");}finally{PhoneBackup.remove(root);}}
}